ALTER TABLE public.mapper_roles ADD COLUMN IF NOT EXISTS member_id uuid DEFAULT gen_random_uuid();
CREATE UNIQUE INDEX IF NOT EXISTS mapper_roles_member_id_key ON public.mapper_roles(member_id);
GRANT ALL ON public.mapper_roles,public.formularios,public.formulario_config,public.formulario_historico,public.formulario_liberacoes,public.notifications TO service_role;
GRANT SELECT,UPDATE ON public.formulario_config TO authenticated;
GRANT SELECT ON public.formulario_config TO anon;
REVOKE ALL ON public.mapper_roles,public.formularios,public.formulario_historico,public.formulario_liberacoes FROM anon,authenticated;
REVOKE ALL ON public.mapper_roles,public.formularios,public.formulario_historico,public.formulario_liberacoes FROM PUBLIC;
GRANT SELECT ON public.formulario_historico TO authenticated;
DROP POLICY IF EXISTS "historico read" ON public.formulario_historico;
CREATE POLICY "historico read scoped" ON public.formulario_historico FOR SELECT TO authenticated USING (public.mapper_is_geral(public.current_user_email()) OR EXISTS(SELECT 1 FROM public.formularios f WHERE f.id=formulario_id AND f.servidor=public.mapper_servidor_of(public.current_user_email()) AND public.is_mapper(public.current_user_email())));
CREATE OR REPLACE FUNCTION public.mapper_access_server(_servidor text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.mapper_is_geral(public.current_user_email()) OR (public.is_mapper(public.current_user_email()) AND public.mapper_servidor_of(public.current_user_email())=_servidor)) $$;
CREATE OR REPLACE FUNCTION public.mapper_current_identity() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN auth.uid() IS NULL THEN NULL ELSE jsonb_build_object('role',public.mapper_role_of(public.current_user_email()),'servidor',public.mapper_servidor_of(public.current_user_email()),'nick',(SELECT nick FROM public.mapper_roles WHERE lower(email)=public.current_user_email())) END $$;
CREATE OR REPLACE FUNCTION public.mapper_list_members() RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_mapper(public.current_user_email()) AND NOT public.mapper_is_geral(public.current_user_email()) THEN RAISE EXCEPTION 'Acesso negado'; END IF; RETURN QUERY SELECT jsonb_build_object('member_id',m.member_id,'email',CASE WHEN public.mapper_is_geral(public.current_user_email()) THEN m.email ELSE NULL END,'role',m.role,'servidor',m.servidor,'nick',m.nick,'rg',m.rg,'protected',lower(m.email)='criarp21@gmail.com','self',lower(m.email)=public.current_user_email()) FROM public.mapper_roles m WHERE public.mapper_is_geral(public.current_user_email()) OR m.servidor=public.mapper_servidor_of(public.current_user_email()) ORDER BY m.created_at; END $$;
CREATE OR REPLACE FUNCTION public.mapper_save_member(_member_id uuid,_email text,_role text,_nick text,_rg text,_servidor text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old public.mapper_roles; clean text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF _role NOT IN ('responsavel_geral','aux_responsavel_geral','responsavel','auxiliar') OR _role IS NULL THEN RAISE EXCEPTION 'Cargo inválido'; END IF; IF _role IN ('responsavel_geral','aux_responsavel_geral') THEN _servidor:=NULL; ELSIF _servidor IS NULL OR _servidor NOT IN ('Servidor 1','Servidor 2','Servidor 3') THEN RAISE EXCEPTION 'Selecione o servidor'; END IF; IF NOT coalesce(public.mapper_can_grant(public.current_user_email(),_role,_servidor),false) THEN RAISE EXCEPTION 'Sem permissão para conceder esse cargo'; END IF; IF nullif(trim(_nick),'') IS NULL OR nullif(trim(_rg),'') IS NULL THEN RAISE EXCEPTION 'Preencha nick e RG'; END IF; IF _member_id IS NOT NULL THEN SELECT * INTO old FROM public.mapper_roles WHERE member_id=_member_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Membro não encontrado'; END IF; IF lower(old.email) IN ('criarp21@gmail.com',public.current_user_email()) OR NOT public.mapper_can_grant(public.current_user_email(),old.role,old.servidor) THEN RAISE EXCEPTION 'Membro protegido ou fora da sua permissão'; END IF; END IF; clean:=lower(trim(coalesce(nullif(_email,''),old.email))); IF clean IS NULL OR clean !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'E-mail inválido'; END IF; IF clean='criarp21@gmail.com' THEN RAISE EXCEPTION 'Conta fundadora protegida'; END IF; IF _member_id IS NULL THEN INSERT INTO public.mapper_roles(email,role,nick,rg,servidor) VALUES(clean,_role,trim(_nick),trim(_rg),_servidor); ELSE UPDATE public.mapper_roles SET email=clean,role=_role,nick=trim(_nick),rg=trim(_rg),servidor=_servidor WHERE member_id=_member_id; END IF; END $$;
CREATE OR REPLACE FUNCTION public.mapper_remove_member(_member_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.mapper_roles; BEGIN SELECT * INTO m FROM public.mapper_roles WHERE member_id=_member_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL OR lower(m.email) IN ('criarp21@gmail.com',public.current_user_email()) OR NOT coalesce(public.mapper_can_grant(public.current_user_email(),m.role,m.servidor),false) THEN RAISE EXCEPTION 'Sem permissão para remover'; END IF; DELETE FROM public.mapper_roles WHERE member_id=_member_id; END $$;
CREATE OR REPLACE FUNCTION public.mapper_list_forms(_id bigint DEFAULT NULL) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.mapper_is_geral(public.current_user_email()) THEN to_jsonb(f) ELSE to_jsonb(f)-'email' END FROM public.formularios f WHERE public.mapper_access_server(f.servidor) AND (_id IS NULL OR f.id=_id) ORDER BY f.data_hora DESC $$;
CREATE OR REPLACE FUNCTION public.mapper_form_history(_id bigint) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.mapper_is_geral(public.current_user_email()) THEN to_jsonb(h) ELSE to_jsonb(h)-'ator' END FROM public.formulario_historico h JOIN public.formularios f ON f.id=h.formulario_id WHERE f.id=_id AND public.mapper_access_server(f.servidor) ORDER BY h.created_at DESC,h.id DESC $$;
CREATE OR REPLACE FUNCTION public.mapper_decide_form(_id bigint,_status text,_motivo text,_revision boolean DEFAULT false) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.formularios; BEGIN SELECT * INTO f FROM public.formularios WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT public.mapper_access_server(f.servidor) THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF _status NOT IN ('analysis','approved','rejected') OR _status IS NULL THEN RAISE EXCEPTION 'Status inválido'; END IF; IF _status IN ('approved','rejected') AND nullif(trim(_motivo),'') IS NULL THEN RAISE EXCEPTION 'Informe o motivo'; END IF; IF _revision AND (NOT coalesce(public.mapper_role_of(public.current_user_email()) IN ('responsavel','responsavel_geral','aux_responsavel_geral'),false) OR f.status NOT IN ('approved','rejected') OR _status=f.status OR _status NOT IN ('approved','rejected')) THEN RAISE EXCEPTION 'Revisão não permitida'; END IF; IF NOT _revision AND NOT ((f.status='pending' AND _status='analysis') OR (f.status='analysis' AND _status IN ('approved','rejected'))) THEN RAISE EXCEPTION 'Status foi alterado; atualize a página'; END IF; UPDATE public.formularios SET status=_status WHERE id=_id; INSERT INTO public.formulario_historico(formulario_id,acao,status_anterior,status_novo,motivo,ator) VALUES(_id,CASE WHEN _revision THEN 'revisao' ELSE _status END,f.status,_status,coalesce(nullif(trim(_motivo),''),'Início da análise'),public.current_user_email()); INSERT INTO public.notifications(tipo,titulo,mensagem,formulario_id,ator) VALUES(_status,CASE WHEN _revision THEN 'Revisão concluída' ELSE 'Inscrição atualizada' END,f.nick||' · '||f.servidor||' · '||coalesce(_motivo,''),_id,public.current_user_email()); RETURN _status; END $$;
CREATE OR REPLACE FUNCTION public.mapper_edit_form(_id bigint,_data jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.formularios; n public.formularios; BEGIN SELECT * INTO f FROM public.formularios WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT public.mapper_access_server(f.servidor) OR NOT coalesce(public.mapper_role_of(public.current_user_email()) IN ('responsavel','responsavel_geral','aux_responsavel_geral'),false) THEN RAISE EXCEPTION 'Sem permissão para editar'; END IF; n:=jsonb_populate_record(f,_data-'id'-'status'-'ip'-'navegador'-'data_hora'); IF NOT public.mapper_access_server(n.servidor) THEN RAISE EXCEPTION 'Servidor fora da sua permissão'; END IF; UPDATE public.formularios SET email=n.email,servidor=n.servidor,nick=n.nick,rg=n.rg,discord=n.discord,"número"=n."número",idade=n.idade,level=n.level,org_corp=n.org_corp,plataforma=n.plataforma,tipo_rp=n.tipo_rp,experiencia_mapeacao=n.experiencia_mapeacao,experiencia_administracao=n.experiencia_administracao,motivo_mapper=n.motivo_mapper,nivel_mapeamento=n.nivel_mapeamento,tempo_cidade=n.tempo_cidade,caracteristicas_mapper=n.caracteristicas_mapper,responsabilidade_propriedades=n.responsabilidade_propriedades,resolucao_erros_mapeamento=n.resolucao_erros_mapeamento WHERE id=_id; END $$;
CREATE OR REPLACE FUNCTION public.mapper_delete_form(_id bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.mapper_is_geral(public.current_user_email()) THEN RAISE EXCEPTION 'Acesso negado'; END IF; DELETE FROM public.formulario_historico WHERE formulario_id=_id; DELETE FROM public.notifications WHERE formulario_id=_id; DELETE FROM public.formularios WHERE id=_id; END $$;
CREATE OR REPLACE FUNCTION public.mapper_create_release(_email text,_nick text,_servidor text,_rg text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.mapper_access_server(_servidor) OR NOT coalesce(public.mapper_role_of(public.current_user_email()) IN ('responsavel','responsavel_geral','aux_responsavel_geral'),false) THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF nullif(trim(_email),'') IS NULL OR nullif(trim(_nick),'') IS NULL OR nullif(trim(_rg),'') IS NULL THEN RAISE EXCEPTION 'Preencha todos os campos'; END IF; INSERT INTO public.formulario_liberacoes(email,nick,servidor,rg) VALUES(lower(trim(_email)),trim(_nick),_servidor,trim(_rg)); END $$;
CREATE OR REPLACE FUNCTION public.mapper_submit_form(_data jsonb) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n public.formularios; lib bigint; new_id bigint; BEGIN n:=jsonb_populate_record(NULL::public.formularios,_data); IF n.servidor IS NULL OR n.servidor NOT IN ('Servidor 1','Servidor 2','Servidor 3') THEN RAISE EXCEPTION 'Servidor inválido'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(lower(coalesce(n.email,''))||lower(coalesce(n.nick,''))||n.servidor||lower(coalesce(n.rg,'')),0)); PERFORM 1 FROM public.formulario_config WHERE servidor=n.servidor AND locked FOR SHARE; IF FOUND THEN RAISE EXCEPTION 'Formulário trancado para este servidor'; END IF; IF nullif(trim(n.email),'') IS NULL OR nullif(trim(n.nick),'') IS NULL OR nullif(trim(n.rg),'') IS NULL THEN RAISE EXCEPTION 'Preencha e-mail, nick e RG'; END IF; IF EXISTS(SELECT 1 FROM public.formularios f WHERE lower(f.email)=lower(n.email) AND lower(f.nick)=lower(n.nick) AND f.servidor=n.servidor AND lower(f.rg)=lower(n.rg) AND f.data_hora>now()-interval '48 hours') THEN SELECT id INTO lib FROM public.formulario_liberacoes WHERE lower(email)=lower(n.email) AND lower(nick)=lower(n.nick) AND servidor=n.servidor AND lower(rg)=lower(n.rg) AND used_at IS NULL ORDER BY created_at DESC LIMIT 1 FOR UPDATE; IF lib IS NULL THEN RAISE EXCEPTION 'Aguarde 48 horas antes de reenviar ou solicite liberação à equipe'; END IF; END IF; new_id:=floor(extract(epoch FROM clock_timestamp())*1000000)::bigint; INSERT INTO public.formularios SELECT (jsonb_populate_record(n,jsonb_build_object('id',new_id,'data_hora',now(),'status','pending'))).*; IF lib IS NOT NULL THEN UPDATE public.formulario_liberacoes SET used_at=now() WHERE id=lib; END IF; RETURN new_id; END $$;
REVOKE ALL ON FUNCTION public.mapper_access_server(text),public.mapper_current_identity(),public.mapper_list_members(),public.mapper_save_member(uuid,text,text,text,text,text),public.mapper_remove_member(uuid),public.mapper_list_forms(bigint),public.mapper_form_history(bigint),public.mapper_decide_form(bigint,text,text,boolean),public.mapper_edit_form(bigint,jsonb),public.mapper_delete_form(bigint),public.mapper_create_release(text,text,text,text),public.mapper_submit_form(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.mapper_access_server(text),public.mapper_current_identity(),public.mapper_list_members(),public.mapper_save_member(uuid,text,text,text,text,text),public.mapper_remove_member(uuid),public.mapper_list_forms(bigint),public.mapper_form_history(bigint),public.mapper_decide_form(bigint,text,text,boolean),public.mapper_edit_form(bigint,jsonb),public.mapper_delete_form(bigint),public.mapper_create_release(text,text,text,text),public.mapper_submit_form(jsonb) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.mapper_submit_form(jsonb) TO anon;
REVOKE SELECT,UPDATE,DELETE ON public.notifications FROM anon;
DROP POLICY IF EXISTS "anon read notifs" ON public.notifications;
DROP POLICY IF EXISTS "auth read notifs" ON public.notifications;
CREATE POLICY "mapper generals read notifications" ON public.notifications FOR SELECT TO authenticated USING(public.mapper_is_geral(public.current_user_email()));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.notifications TO authenticated;
GRANT INSERT ON public.notifications TO anon;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO authenticated,anon;